def qdrantHybridSearch(query, model):
    """
    Perform a hybrid search using an input query. The query is embedded and the embeddings are compared to embeddings
    from the datapoints already in the vector database. The top 1000 chunks with dense vectors closest to the query are
    returned as are the top 1000 chunks that match keywords in the query. Reciprocal Rank Fusion (RRF) is used to merge
    the results from sparse vector and dense vector retrievals into a single ranked list without duplicates. RRF
    considers the positions of results within each query and boosts those that appear closer to the top in multiple
    sets of results. ColBERT reranks the list using MAX_SIM to create a list of 10 chunks that can answer the user's
    query.

    :param query: A text-based query for information. "Return functional data about the following variant: LDLR c.301G>A"
    :param model: BAAI/bge-m3 embedding model from Hugging Face.
    :return: results from the search
    """

    # Connect to the Qdrant interface on your local machine.
    client = QdrantClient(url="http://localhost:6333")

    # Encode the query into dense, sparse and ColBERT vectors using the BGE-M3 model.
    encoded = model.encode(query, return_dense=True, return_sparse=True, return_colbert_vecs=True)

    # Assign the dense vector to the 'dense' variable.
    dense = encoded['dense_vecs'].astype("float32").tolist()

    # Assign the ColBERT vectors to the 'colbert' variable.
    colbert = encoded['colbert_vecs'].astype("float32").tolist()

    # Embeddings of each word (tokens) in the query is added to the 'indices' list.
    indices = []
    # The lexical weight of each embedding is added to the 'values' list.
    values = []

    # Tokens and weights are extracted and appended into the corresponding lists.
    sparse_dict = encoded['lexical_weights']
    for key, value in sparse_dict.items():
        indices.append(int(key))
        values.append(float(value))

    # The query_points function is used to find data points in the vector database.
    # ** https://qdrant.tech/documentation/search/hybrid-queries/#reciprocal-rank-fusion-rrf **
    result = client.query_points(
        collection_name="FH_PDFs",
        prefetch=models.Prefetch(
            prefetch=[
                # The top 1000 chunks with the closest distance to the query are returned.
                models.Prefetch(
                    query=dense,
                    using="dense",
                    limit=1000,
                ),
                # The top 1000 chunks with the closest keywords to the query are returned.
                models.Prefetch(
                    query=models.SparseVector(indices=indices, values=values),
                    using="sparse",
                    limit=1000,
                ),
            ],
            # RRF is used to merge the results from dense and sparse vector searches into a single list.
            query=models.FusionQuery(fusion=models.Fusion.RRF),
        ),
        # ColBERT is then used to rerank the list into a final list of 10 chunks.
        query=colbert,  # <-- full vector
        using="colbert",
        limit=10,
    )

    client.close()

    print("---HybridSearch complete.")

    # The chunks are then returned.
    return result

